    # Actually, let's find the dividing row and column.
    # A dividing line is typically a full row or full col of a single color (like 1, 2, or 3).
    div_r = -1
    div_c = -1

    for r in range(R):
        vals = set(grid[r])
        if len(vals) == 1 and list(vals)[0] != 0:
            div_r = r
            break

    for c in range(C):
        vals = set(grid[r][c] for r in range(R))
        if len(vals) == 1 and list(vals)[0] != 0:
            div_c = c
            break

    if div_r == -1:
        div_r = R // 2
    if div_c == -1:
        div_c = C // 2

    # Define the four quadrants
    # Q1: top-left, Q2: top-right, Q3: bottom-left, Q4: bottom-right
    # We want to extract a 3x3 (or bounding box shifted) region for each quadrant.
    # Usually quadrants have fixed size or we can find the bounding box of non-zero elements in each quadrant.

    quadrants = [
        (0, 0, div_r, div_c),                   # TL
        (0, div_c + 1, div_r, C),               # TR
        (div_r + 1, 0, R, div_c),               # BL
        (div_r + 1, div_c + 1, R, C)            # BR
    ]

    extracted = []
    for r1, c1, r2, c2 in quadrants:
        # Find bounding box of non-zero elements in this quadrant
        min_r, max_r = R, -1
        min_c, max_c = C, -1
        for r in range(r1, r2):
            for c in range(c1, c2):
                if grid[r][c] != 0:
                    if r < min_r: min_r = r
                    if r > max_r: max_r = r
                    if c < min_c: min_c = c
                    if c > max_c: max_c = c

        sub = [[0]*3 for _ in range(3)]
        if min_r <= max_r:
            # Extract and place into 3x3
            # To preserve relative position, let's align top-left of bounding box to (0,0) of the 3x3
            for r in range(min_r, min(max_r + 1, min_r + 3)):
