                    sub[r - min_r][c - min_c] = grid[r][c]
        extracted.append(sub)

    # Combine into 6x6
    output = [[0]*6 for _ in range(6)]

    # TL -> output[0:3][0:3]
    for r in range(3):
        for c in range(3):
            output[r][c] = extracted[0][r][c]

    # TR -> output[0:3][3:6]
    for r in range(3):
