            output[r][c+3] = extracted[1][r][c]

    # BL -> output[3:6][0:3]
    for r in range(3):
        for c in range(3):
            output[r+3][c] = extracted[2][r][c]

    # BR -> output[3:6][3:6]
    for r in range(3):
        for c in range(3):
            output[r+3][c+3] = extracted[3][r][c]

    return output

