                    if c_idx < min_c: min_c = c_idx
                    if c_idx > max_c: max_c = c_idx
        height = max_r - min_r + 1
        width = max_c - min_c + 1
        color_stats.append((c, height, width))

    # Sort colors by height descending, then width descending
    color_stats.sort(key=lambda x: (x[1], x[2]), reverse=True)

