        for r in range(R - p):
            for c in range(C):
                if grid[r][c] != 0 and grid[r+p][c] != 0 and grid[r][c] != grid[r+p][c]:
                    match = False
                    break
            if not match:
                break
        if match:
            row_period = p
            break

