    import copy
    R = len(grid)
    C = len(grid[0])
    out = copy.deepcopy(grid)

    # Identify seeds
    seeds = []
    for r in range(R):
        for c in range(C):
            val = grid[r][c]
            if val != 0 and val != 5:
                seeds.append((r, c, val))

    # We want each seed to flood its local compartment of 0s and 5s.
    # A 5-cell is passable if it's part of a thin wall, or more simply, 
    # we can do a multi-source BFS where 0s are fully passable, 
    # and 5s are passable ONLY if they have at most one adjacent 5 (meaning it's a thin wall/edge),
    # preventing traversal through thick 5-walls.

    def is_thin_wall(r, c):
        # Count 5 neighbors
        count = 0
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                if grid[nr][nc] == 5:
                    count += 1
            else:
                count += 1 # consider edge as wall
        return count <= 2

    from collections import deque
    queue = deque()
    visited = [[False] * C for _ in range(R)]

    for r, c, val in seeds:
        visited[r][c] = True
        queue.append((r, c, val))

    while queue:
        r, c, color = queue.popleft()
        out[r][c] = color

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and not visited[nr][nc]:
                target = grid[nr][nc]
                if target == 0:
                    visited[nr][nc] = True
                    queue.append((nr, nc, color))
                elif target == 5:
                    # Can expand into 5 if it's a thin wall / border of the compartment
                    if is_thin_wall(nr, nc):
                        visited[nr][nc] = True
                        queue.append((nr, nc, color))

    return out

