    # In examples 1 & 2, the grid is entirely made of background colors and noise 6).
    # Let's find all (r, c) where grid[r][c] != 6.
    known = {}
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 6:
                known[(r, c)] = grid[r][c]

    # Find the periodic pattern by testing coordinate remainders.
    # Usually, patterns repeat every 2 rows/cols or 3 rows/cols.
    # Let's test periods from 1 to 4 for both row and column to find a consistent mapping.
    best_period_r = 1
    best_period_c = 1
    best_mapping = {}

    from collections import Counter, defaultdict

    for pr in range(1, 5):
        for pc in range(1, 5):
            mapping = defaultdict(list)
            consistent = True
            for (r, c), val in known.items():
                mapping[(r % pr, c % pc)].append(val)

            # Check if each remainder pair maps predominantly to a single value
            conflict_count = 0
            single_valued_mapping = {}
            for k, vals in mapping.items():
                most_common_val, count = Counter(vals).most_common(1)[0]
                single_valued_mapping[k] = most_common_val
                if count < len(vals):
